using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json;
using Microsoft.Extensions.AI;
using Microsoft.Agents.AI;

var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable to run this app.");

var modelId = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini-2024-07-18";

// --- Tool definitions -----------------------------------------------------------

var researchTools = new ResearchTools();
IList<AITool> tools =
[
    AIFunctionFactory.Create(researchTools.SearchWeb),
    AIFunctionFactory.Create(researchTools.AddNote),
    AIFunctionFactory.Create(researchTools.GetNotes),
];

// --- Build the agent ------------------------------------------------------------

IChatClient chatClient = new OpenAI.OpenAIClient(apiKey)
    .GetChatClient(modelId)
    .AsIChatClient();

var agentOptions = new ChatClientAgentOptions
{
    Name = "ResearchAgent",
    Description = "An agent that researches a topic by searching the web and taking notes.",
    ChatOptions = new ChatOptions
    {
        Temperature = 0f,
        MaxOutputTokens = 2048,
        Tools = tools,
    },
};

ChatClientAgent agent = chatClient.AsAIAgent(agentOptions);

// --- Run the agent --------------------------------------------------------------

Console.WriteLine("=== Research Agent ===");
Console.Write("Enter a topic to research: ");
var topic = Console.ReadLine()?.Trim();

if (string.IsNullOrWhiteSpace(topic))
{
    Console.WriteLine("No topic provided. Exiting.");
    return;
}

var instructions = $"""
    You are a research assistant. Your goal is to research the following topic
    and produce a concise, well-structured summary.

    Topic: {topic}

    Follow these steps:
    1. Search the web for information about the topic (2-3 different searches with
       varied queries to get broad coverage).
    2. For each useful finding, add a note capturing the key information.
    3. After gathering enough information, retrieve all your notes.
    4. Produce a final summary that synthesizes the findings. Include source URLs.

    Be thorough but concise. Focus on facts and key insights.
    """;

var session = await agent.CreateSessionAsync();
var response = await agent.RunAsync(instructions, session);

Console.WriteLine();
Console.WriteLine("=== Research Summary ===");
Console.WriteLine(response.Text);

// --- Tool implementations -------------------------------------------------------

sealed class ResearchTools
{
    private static readonly HttpClient s_httpClient = new()
    {
        Timeout = TimeSpan.FromSeconds(15),
    };

    private readonly List<string> _notes = [];

    [Description("Search the web for information on a query. Returns a list of results with titles, snippets, and URLs.")]
    public async Task<string> SearchWeb(
        [Description("The search query string")] string query)
    {
        Console.WriteLine($"  [Tool] Searching the web for: \"{query}\"");

        try
        {
            // Use DuckDuckGo Instant Answer API (no key required)
            var encoded = Uri.EscapeDataString(query);
            var url = $"https://api.duckduckgo.com/?q={encoded}&format=json&no_html=1&skip_disambig=1";

            var json = await s_httpClient.GetFromJsonAsync<JsonElement>(url);

            var results = new List<string>();

            // Extract abstract if available
            var abstractText = json.GetProperty("AbstractText").GetString();
            var abstractUrl = json.GetProperty("AbstractURL").GetString();
            if (!string.IsNullOrWhiteSpace(abstractText))
            {
                results.Add($"[Abstract] {abstractText}\nSource: {abstractUrl}");
            }

            // Extract related topics
            if (json.TryGetProperty("RelatedTopics", out var topics))
            {
                foreach (var item in topics.EnumerateArray().Take(5))
                {
                    if (item.TryGetProperty("Text", out var text)
                        && item.TryGetProperty("FirstURL", out var itemUrl))
                    {
                        results.Add($"- {text.GetString()}\n  URL: {itemUrl.GetString()}");
                    }
                }
            }

            if (results.Count == 0)
            {
                return $"No results found for \"{query}\". Try a different search query.";
            }

            return string.Join("\n\n", results);
        }
        catch (Exception ex)
        {
            return $"Search failed: {ex.Message}. Try a different query.";
        }
    }

    [Description("Save a research note. Use this to record important findings as you research.")]
    public string AddNote(
        [Description("The note content to save")] string note)
    {
        _notes.Add(note);
        Console.WriteLine($"  [Tool] Note #{_notes.Count} saved ({note.Length} chars)");
        return $"Note #{_notes.Count} saved.";
    }

    [Description("Retrieve all saved research notes.")]
